       elapsed_ns = self.last_update_time_ns - self.first_update_time_ns
       intervals = self.total_received - 1
       if intervals == 0:
           return 0.0
       avg_interval_ns = elapsed_ns / intervals
       return avg_interval_ns / 1_000_000

